package com.shopsphere.filter; import com.shopsphere.model.User;import jakarta.servlet.*;import jakarta.servlet.annotation.WebFilter;import jakarta.servlet.http.*;import java.io.*;@WebFilter({"/cart","/checkout","/orders"})public class AuthenticationFilter implements Filter{public void doFilter(ServletRequest a,ServletResponse b,FilterChain c)throws IOException,ServletException{HttpServletRequest r=(HttpServletRequest)a;HttpSession s=r.getSession(false);if(s==null||s.getAttribute("user")==null){((HttpServletResponse)b).sendRedirect(r.getContextPath()+"/login.jsp");return;}c.doFilter(a,b);}}
